-- Phase 2 (Shopify, read-only): token lifecycle metadata for integration connections.

-- AlterTable (generated by `prisma migrate diff`)
ALTER TABLE "integration_connections" ADD COLUMN     "access_token_expires_at" TIMESTAMP(3),
ADD COLUMN     "connected_at" TIMESTAMP(3),
ADD COLUMN     "refresh_token_expires_at" TIMESTAMP(3);

-- -----------------------------------------------------------------------------
-- Safety constraints (hand-written; Prisma cannot express these in the schema).
-- -----------------------------------------------------------------------------

-- Credentials are only ever stored as versioned AES-256-GCM ciphertext
-- ("v1.<iv>.<tag>.<ciphertext>", base64url) — a plaintext token cannot be saved.
ALTER TABLE "integration_connections"
  ADD CONSTRAINT "integration_connections_encrypted_credentials_check"
  CHECK (
    "encrypted_credentials" IS NULL
    OR "encrypted_credentials" ~ '^v1\.[A-Za-z0-9_-]+\.[A-Za-z0-9_-]+\.[A-Za-z0-9_-]+$'
  );

-- A CONNECTED row must carry credentials; a REVOKED row must not keep any.
ALTER TABLE "integration_connections"
  ADD CONSTRAINT "integration_connections_status_credentials_check"
  CHECK (
    ("status" <> 'CONNECTED' OR "encrypted_credentials" IS NOT NULL)
    AND ("status" <> 'REVOKED' OR "encrypted_credentials" IS NULL)
  );

-- At most one current (CONNECTED or ERROR) connection per provider per workspace.
CREATE UNIQUE INDEX "integration_connections_one_current_per_provider"
  ON "integration_connections" ("workspace_id", "provider")
  WHERE "status" IN ('CONNECTED', 'ERROR');
